var b=WebApplication.CreateBuilder(args); b.Services.AddControllersWithViews(); b.Services.AddDistributedMemoryCache(); b.Services.AddSession(o=>{o.Cookie.HttpOnly=true;o.Cookie.IsEssential=true;o.IdleTimeout=TimeSpan.FromMinutes(30);}); b.Services.AddHttpContextAccessor(); b.Services.AddScoped<RaceDayApi>(); var app=b.Build(); if(!app.Environment.IsDevelopment()){app.UseExceptionHandler("/Home/Error");app.UseHsts();} app.UseHttpsRedirection();app.UseStaticFiles();app.UseRouting();app.UseSession();app.MapControllerRoute("default","{controller=Home}/{action=Index}/{id?}");app.Run();